def get_icon_svg(name: str, color: str = "#38BDF8", size: int = 18) -> str:
    """Return rendered SVG string for named icon with fallback."""
    tmpl = ICONS.get(name, ICONS["shield"])
    return tmpl.format(color=color, size=size)


def card_metric_html(
    title: str,
    value: str,
    subtitle: str,
    icon_name: str,
    accent_color: str = "#38BDF8",
    badge: Optional[str] = None,
    badge_color: str = "#10B981",
) -> str:
    """Render sleek modern enterprise metric card with pop-up hover effect and zero markdown indentation."""
    icon_svg = get_icon_svg(icon_name, color=accent_color, size=20)
    badge_markup = ""
    if badge:
        badge_markup = (
            f'<span style="font-size:11px;font-weight:700;background:{badge_color}22;'
            f'color:{badge_color};border:1px solid {badge_color}55;padding:2px 8px;'
            f'border-radius:9999px;letter-spacing:0.3px;">{badge}</span>'
        )

    # Compact single-line / unindented HTML prevents Streamlit Markdown code block parsing
    html = (
        f'<div class="metric-card-box" style="border-top:3px solid {accent_color};">'
        f'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">'
        f'<span style="color:#94A3B8;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.6px;">{title}</span>'
        f'<div style="display:flex;align-items:center;gap:6px;">'
        f'{badge_markup}'
        f'<div style="background:#0F172A;border:1px solid #334155;border-radius:6px;padding:5px;display:flex;align-items:center;justify-content:center;">'
        f'{icon_svg}'
        f'</div>'
        f'</div>'
        f'</div>'
        f'<div style="color:#F8FAFC;font-size:24px;font-weight:800;letter-spacing:-0.5px;line-height:1.2;">{value}</div>'
        f'<div style="color:#64748B;font-size:12px;font-weight:500;margin-top:6px;">{subtitle}</div>'
        f'</div>'
    )
    return html


def section_header_html(
    title: str,
    subtitle: str,
    icon_name: str,
    icon_color: str = "#38BDF8",
    badge: Optional[str] = None,
) -> str:
    """Render clean, high-impact section title with vector icon and optional badge without markdown indentations."""
    icon_svg = get_icon_svg(icon_name, color=icon_color, size=20)
    badge_html = (
        f'<span style="font-size:11px;font-weight:700;background:{icon_color}22;color:{icon_color};border:1px solid {icon_color}55;padding:2px 8px;border-radius:6px;margin-left:8px;">{badge}</span>'
        if badge
        else ""
    )
    html = (
        f'<div style="margin-top:20px;margin-bottom:14px;">'
        f'<div style="display:flex;align-items:center;gap:10px;">'
        f'<div style="background:#0F172A;border:1px solid #334155;border-radius:8px;padding:6px;display:flex;align-items:center;justify-content:center;">'
        f'{icon_svg}'
        f'</div>'
        f'<div style="display:flex;align-items:center;">'
        f'<span style="color:#F8FAFC;font-size:18px;font-weight:800;letter-spacing:-0.4px;">{title}</span>'
        f'{badge_html}'
        f'</div>'
        f'</div>'
        f'<div style="color:#94A3B8;font-size:12.5px;margin-top:3px;margin-left:42px;">{subtitle}</div>'
        f'</div>'
    )
    return html


def status_pill_html(status: str) -> str:
    """Render color-coded status badge pill without markdown indentations."""
    status_upper = str(status).upper()
    if "TRIP" in status_upper or "FAIL" in status_upper:
        color = "#EF4444"
        bg = "rgba(239, 68, 68, 0.15)"
        border = "rgba(239, 68, 68, 0.4)"
        icon = "●"
    elif "ACTIVE" in status_upper or "STREAM" in status_upper:
        color = "#38BDF8"
        bg = "rgba(56, 189, 248, 0.15)"
        border = "rgba(56, 189, 248, 0.4)"
        icon = "●"
    elif "COMPLET" in status_upper or "PASS" in status_upper or "SAVE" in status_upper:
        color = "#10B981"
        bg = "rgba(16, 185, 129, 0.15)"
        border = "rgba(16, 185, 129, 0.4)"
        icon = "✓"
    else:
        color = "#A855F7"
        bg = "rgba(168, 85, 247, 0.15)"
        border = "rgba(168, 85, 247, 0.4)"
        icon = "ℹ"

    return (
        f'<span style="display:inline-flex;align-items:center;gap:5px;font-size:11px;font-weight:700;'
        f'color:{color};background:{bg};border:1px solid {border};padding:2px 9px;border-radius:9999px;'
        f'text-transform:uppercase;letter-spacing:0.5px;"><span style="font-size:8px;">{icon}</span> {status_upper}</span>'
    )
